auto live_rng(const LiveSessionState &s){return std::array{s.random.map.state(),s.random.gameplay.state()};}
auto raw_rng(const LiveSessionState &s){std::array<SimulationRandomState,2> out;for(std::size_t k=0;k<2;++k){const auto &v=s.world.progression.random[k];out[k]={v.seed,v.calls,v.resets};}return out;}
// Proof of draw-only succession, not a second random-number producer.
// Matches the progression relation checked by bnw_live_rng_export.
