void successor(const SimulationRandomState &now,const SimulationRandomState &old){need(now.seed<=UINT32_MAX&&old.seed<=UINT32_MAX&&now.resets==old.resets&&now.calls>=old.calls&&now.seed==successor_seed(old.seed,now.calls-old.calls),"BNW first Grand roll current RNG is not a draw-only source successor");}
